for (const metro of michiganBatch2.metros) {
  for (const service of metro.services) {
    const note = michiganServiceNotes[`${metro.slug}:${service.serviceSlug}`];
    if (!note) continue;
    service.permitAuthority += ` ${note.authority}`;
    service.codeContext += ` ${note.code}`;
    service.localConditions += ` ${note.local}`;
    service.projectTypes += ` ${note.project}`;
    service.sections = [...service.sections, note.section];
    // Put the locally researched intake checkpoint first: the remaining steps
    // retain the page's discipline-specific coordination, rather than a shared
    // metro-wide workflow.
    service.permitSteps = [note.permit, ...service.permitSteps.slice(0, 3)];
    service.faqs = [...service.faqs, note.faq];
  }
}